ories":80,"base_attrs":{"strength":4,"dexterity":3,"vitality":2,"wisdom":4,"spirit":3},"available_fields":["NSo","DR","NSp","DS"],"signature_technique":"Ultimate Ouryuken","evolution_text":""},{"source_name":"Alphamon","name":"Alphamon","stage":"Mega","fields":["DR","VB","NSo","NSp"],"hp_base":6,"suggested_hp":8,"stabilization_victories":80,"base_attrs":{"strength":5,"dexterity":3,"vitality":2,"wisdom":2,"spirit":4},"available_fields":["DR","VB","NSo","NSp"],"signature_technique":"Blade of the Dragon King","evolution_text":""},{"source_name":"UltimateBrachiomon","name":"UltimateBrachiomon","stage":"Mega","fields":["ME","JT","VB","NSo"],"hp_base":6,"suggested_hp":10,"stabilization_victories":80,"base_attrs":{"strength":3,"dexterity":3,"vitality":4,"wisdom":2,"spirit":4},"available_fields":["ME","JT","VB","NSo"],"signature_technique":"Ultimate Blast","evolution_text":""},{"source_name":"Argomon","name":"Argomon (Mega)","stage":"Mega","fields":["VB","NSo","DR","NSp"],"hp_base":6,"suggested_hp":8,"stabilization_victories":80,"base_attrs":{"strength":4,"dexterity":4,"vitality":2,"wisdom":3,"spirit":3},"available_fields":["VB","NSo","DR","NSp"],"signature_technique":"Brute Force","evolution_text":""},{"source_name":"Apollomon","name":"Apollomon","stage":"Mega","fields":["JT","VB","NSo","DR"],"hp_base":6,"suggested_hp":10,"stabilization_victories":80,"base_attrs":{"strength":3,"dexterity":3,"vitality":4,"wisdom":3,"spirit":3},"available_fields":["JT","VB","NSo","DR"],"signature_technique":"Arrow of Apollo","evolution_text":""},{"source_name":"Apocalymon","name":"Apocalymon","stage":"Mega","fields":["NSo","VB","DR","NSp"],"hp_base":6,"suggested_hp":9,"stabilization_victories":80,"base_attrs":{"strength":3,"dexterity":3,"vitality":3,"wisdom":3,"spirit":4},"available_fields":["NSo","VB","DR","NSp"],"signature_technique":"Darkness-Zone","evolution_text":""},{"source_name":"Anubismon","name":"Anubismon","stage":"Mega","fields":["ME","JT","VB","NSo"],"hp_base":6,"suggested_hp":9,"stabilization_victories":80,"base_attrs":{"strength":3,"dexterity":3,"vitality":3,"wisdom":3,"spirit":4},"available_fields":["ME","JT","VB","NSo"],"signature_technique":"Amemit","evolution_text":""},{"source_name":"Armageddemon","name":"Armageddemon","stage":"Mega","fields":["NSo","DR","NSp","DS"],"hp_base":6,"suggested_hp":8,"stabilization_victories":80,"base_attrs":{"strength":4,"dexterity":2,"vitality":2,"wisdom":4,"spirit":4},"available_fields":["NSo","DR","NSp","DS"],"signature_technique":"Black Rain","evolution_text":""},{"source_name":"AvengeKidmon","name":"AvengeKidmon","stage":"Mega","fields":["DS","WG","ME","JT"],"hp_base":6,"suggested_hp":9,"stabilization_victories":80,"base_attrs":{"strength":3,"dexterity":4,"vitality":3,"wisdom":3,"spirit":3},"available_fields":["DS","WG","ME","JT"],"signature_technique":"Destruction Trigger","evolution_text":""}]$catalog$::jsonb);

update public.digirole_species existing
set name = imported.name
from jsonb_to_recordset((select payload from _digirole_species_import)) as imported(source_name text,name text,stage text)
where lower(btrim(existing.name)) = lower(btrim(imported.source_name))
  and existing.stage = imported.stage
  and existing.name <> imported.name
  and not exists (select 1 from public.digirole_species occupied where lower(btrim(occupied.name))=lower(btrim(imported.name)));

update public.digirole_species existing set
  stage=imported.stage, fields=imported.fields, available_fields=imported.available_fields,
  hp_base=imported.hp_base, suggested_hp=imported.suggested_hp,
  stabilization_text=case when imported.stabilization_victories=0 then 'Automática.' else imported.stabilization_victories||' vitórias nesta forma.' end,
  stabilization_victories=imported.stabilization_victories,
  base_attrs=imported.base_attrs || jsonb_build_object('charisma',coalesce(nullif(existing.base_attrs->>'charisma','')::integer,1)),
  signature_technique=imported.signature_technique, evolution_text=imported.evolution_text, updated_at=now()
from jsonb_to_recordset((select payload from _digirole_species_import)) as imported(name text,stage text,fields text[],available_fields text[],hp_base integer,suggested_hp integer,stabilization_victories integer,base_attrs jsonb,signature_technique text,evolution_text text)
where lower(btrim(existing.name))=lower(btrim(imported.name));

insert into public.digirole_species(name,stage,fields,available_fields,hp_base,suggested_hp,stabilization_text,stabilization_victories,base_attrs,signature_technique,evolution_text)
select imported.name,imported.stage,imported.fields,imported.available_fields,imported.hp_base,imported.suggested_hp,
  case when imported.stabilization_victories=0 then 'Automática.' else imported.stabilization_victories||' vitórias nesta forma.' end,
  imported.stabilization_victories,imported.base_attrs||'{"charisma":1}'::jsonb,imported.signature_technique,imported.evolution_text
from jsonb_to_recordset((select payload from _digirole_species_import)) as imported(name text,stage text,fields text[],available_fields text[],hp_base integer,suggested_hp integer,stabilization_victories integer,base_attrs jsonb,signature_technique text,evolution_text text)
where not exists(select 1 from public.digirole_species existing where lower(btrim(existing.name))=lower(btrim(imported.name)));

update public.digirole_species_techniques link set is_signature=false
where link.species_id in (
  select catalog.id from public.digirole_species catalog
  join jsonb_to_recordset((select payload from _digirole_species_import)) as imported(name text)
    on lower(btrim(catalog.name))=lower(btrim(imported.name))
);
